PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE products (product_code TEXT PRIMARY KEY, name TEXT, max_coverage TEXT, base_rate TEXT, effective_from TEXT, effective_to TEXT);
CREATE TABLE applicants (applicant_id TEXT PRIMARY KEY, name TEXT, region TEXT, created_date TEXT);
CREATE TABLE insured_assets (asset_id TEXT PRIMARY KEY, applicant_id TEXT, product_code TEXT, asset_type TEXT, declared_value TEXT, risk_score TEXT, created_date TEXT, FOREIGN KEY (applicant_id) REFERENCES applicants(applicant_id), FOREIGN KEY (product_code) REFERENCES products(product_code));
CREATE TABLE coverage_options (coverage_id TEXT PRIMARY KEY, product_code TEXT, name TEXT, limit_amount TEXT, effective_from TEXT, effective_to TEXT, FOREIGN KEY (product_code) REFERENCES products(product_code));
CREATE TABLE risk_factors (risk_factor_id TEXT PRIMARY KEY, asset_id TEXT, factor_name TEXT, factor_value TEXT, factor_multiplier TEXT, effective_from TEXT, effective_to TEXT, FOREIGN KEY (asset_id) REFERENCES insured_assets(asset_id));
CREATE TABLE quotes (quote_id TEXT PRIMARY KEY, applicant_id TEXT, asset_id TEXT, product_code TEXT, requested_coverage TEXT, risk_score TEXT, premium TEXT, decision TEXT, reason TEXT, created_date TEXT, FOREIGN KEY (applicant_id) REFERENCES applicants(applicant_id), FOREIGN KEY (asset_id) REFERENCES insured_assets(asset_id), FOREIGN KEY (product_code) REFERENCES products(product_code));
CREATE TABLE underwriting_decisions (decision_id TEXT PRIMARY KEY, quote_id TEXT, outcome TEXT, reason TEXT, authority_level TEXT, decided_date TEXT, FOREIGN KEY (quote_id) REFERENCES quotes(quote_id));
CREATE TABLE policies (policy_id TEXT PRIMARY KEY, quote_id TEXT, applicant_id TEXT, asset_id TEXT, product_code TEXT, coverage_amount TEXT, premium TEXT, status TEXT, accepted TEXT, payment_received TEXT, start_date TEXT, end_date TEXT, FOREIGN KEY (quote_id) REFERENCES quotes(quote_id), FOREIGN KEY (applicant_id) REFERENCES applicants(applicant_id), FOREIGN KEY (asset_id) REFERENCES insured_assets(asset_id), FOREIGN KEY (product_code) REFERENCES products(product_code));
CREATE TABLE endorsements (endorsement_id TEXT PRIMARY KEY, policy_id TEXT, change_type TEXT, coverage_delta TEXT, proposed_coverage TEXT, prior_asset_id TEXT, replacement_asset_id TEXT, status TEXT, effective_date TEXT, FOREIGN KEY (policy_id) REFERENCES policies(policy_id), FOREIGN KEY (prior_asset_id) REFERENCES insured_assets(asset_id), FOREIGN KEY (replacement_asset_id) REFERENCES insured_assets(asset_id));
CREATE TABLE renewals (renewal_id TEXT PRIMARY KEY, policy_id TEXT, offered_premium TEXT, status TEXT, response TEXT, offer_date TEXT, renewal_date TEXT, FOREIGN KEY (policy_id) REFERENCES policies(policy_id));
CREATE TABLE policy_events (event_id TEXT PRIMARY KEY, policy_id TEXT, event_type TEXT, event_date TEXT, details TEXT, FOREIGN KEY (policy_id) REFERENCES policies(policy_id));
CREATE TABLE ground_truth (issue_id TEXT PRIMARY KEY, issue_type TEXT, entity TEXT, record_id TEXT, expected_decision TEXT, details TEXT);
COMMIT;
